/* Service worker — offline application shell.
 * Generated by tools/build.ps1 (the file list and version below are filled in at build time).
 * Strategy: every application file is pre-cached under a versioned cache name and served cache-first, so the app
 * opens and works with no connection. Only same-origin GET requests are handled; requests to any other origin
 * (the optional sync endpoint) are never intercepted or cached. Audit data is not stored here — it lives in IndexedDB. */
const VERSION = 'ee5f756231e5';
/* The cache belongs to this copy of the application: its name carries the folder the worker is served from, so two
   copies on one origin (a staging folder next to a production one, for example) never share or delete each other's. */
const HOME = new URL('./', self.location.href).pathname;
const PREFIX = 'av-environment-intelligence-' + HOME + '-';
/* the name earlier versions used for this copy's cache: removed when this version activates */
const LEGACY_PREFIX = 'evcr-av-intelligence-' + HOME + '-';
const CACHE = PREFIX + VERSION;
const FILES = [
  './',
  './css/app.css',
  './icons/apple-touch-icon.png',
  './icons/icon-192.png',
  './icons/icon-512.png',
  './icons/icon-maskable-512.png',
  './index.html',
  './js/actions.js',
  './js/auth.js',
  './js/core.js',
  './js/exporter.js',
  './js/handoff.js',
  './js/main.js',
  './js/pages/audits.js',
  './js/pages/backlog.js',
  './js/pages/command.js',
  './js/pages/coordination.js',
  './js/pages/devices.js',
  './js/pages/environment.js',
  './js/pages/export.js',
  './js/pages/infrastructure.js',
  './js/pages/reports.js',
  './js/pages/settings.js',
  './js/pages/spares.js',
  './js/pdf.js',
  './js/photos.js',
  './js/reports.js',
  './js/roomimport.js',
  './js/rules.js',
  './js/schema.js',
  './js/shell.js',
  './js/store.js',
  './js/sync.js',
  './js/ui.js',
  './js/xlsx.js',
  './js/zip.js',
  './manifest.webmanifest'
];

self.addEventListener('install', function (event) {
  /* cache: 'reload' fetches every file from the server, never from the browser's HTTP cache: a host may let the browser
     keep a file for minutes (GitHub Pages: 10), and a new version must not be filled with the files of the previous one */
  const fresh = FILES.map(function (f) { return new Request(f, { cache: 'reload' }); });
  event.waitUntil(caches.open(CACHE).then(function (cache) { return cache.addAll(fresh); }).then(function () { return self.skipWaiting(); }));
});
self.addEventListener('activate', function (event) {
  event.waitUntil(caches.keys().then(function (keys) {
    /* earlier versions of this copy only */
    return Promise.all(keys.filter(function (k) { return (k.indexOf(PREFIX) === 0 && k !== CACHE) || k.indexOf(LEGACY_PREFIX) === 0; }).map(function (k) { return caches.delete(k); }));
  }).then(function () { return self.clients.claim(); }));
});
/* the page asks which version it is running (shown in Settings) */
self.addEventListener('message', function (event) {
  if (event.data === 'version' && event.source) event.source.postMessage({ type: 'version', version: VERSION });
});
self.addEventListener('fetch', function (event) {
  const req = event.request;
  if (req.method !== 'GET') return;
  const url = new URL(req.url);
  if (url.origin !== self.location.origin) return;
  event.respondWith(caches.open(CACHE).then(function (cache) {
    return cache.match(req, { ignoreSearch: true }).then(function (hit) {
      if (hit) return hit;
      return fetch(req).catch(function () {
        if (req.mode === 'navigate') return cache.match('./index.html');
        return new Response('', { status: 504, statusText: 'Offline' });
      });
    });
  }));
});
